using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ReefSongCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/ReefSongCustomDescription", order = 0)]
public class ReefSongCustomDescription : CustomBattleActionDescription
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return Smart.Format(GetRawLocalizedDescription(battleAction), playerEffectsList.ReefSongEffect.IncreaseVirtuesPurificationAmount, GetAmountWithoutEquation(amountModified));
	}
}
